**JSON 직렬화 패턴** (FV-Lang 수동 방식):

```fvlang
fn pipeline_result_to_json(result: PipelineResult) -> String {
    let mut json = String::new();
    json.push_str("{");
    json.push_str("\"success\":");
    json.push_str(if result.success { "true" } else { "false" });
    json.push_str(",\"user_intent\":\"");
    json.push_str(result.user_intent.as_str());
    json.push_str("\",\"patches_applied\":");
    json.push_str(&result.patches_applied.to_string());
    json.push_str(",\"healing_success_rate\":");
    json.push_str(&result.healing_success_rate.to_string());
    json.push_str(",\"learning_rate\":");
    json.push_str(&result.learning_rate.to_string());
    json.push_str(",\"execution_time_ms\":");
    json.push_str(&result.execution_time_ms.to_string());
    json.push_str("}");
    json
}
```

