`render_ascii_bar` 구현 패턴:

```fvlang
fn render_ascii_bar(label: String, value: f32, max_value: f32, width: i32) -> String {
    let filled = ((value / max_value) * (width as f32)) as i32;
    let empty = width - filled;
    let mut bar = String::new();
    bar.push_str(label.as_str());
    bar.push_str(" [");
    for _i in 0..filled { bar.push_str("█"); }
    for _i in 0..empty  { bar.push_str("░"); }
    bar.push_str("] ");
    bar.push_str(&value.to_string());
    bar.push_str("%");
    bar
}
```

